describe('listing conversations', () => {
  it('answers list_sessions from the threaded sessionStore for session.userId off the turn lock', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const gate = deferred();
    const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const sessionStore = {
      listFor: async (userId: string | number, options?: SessionListOptions) => {
        calls.push({userId, options});
        return summaries;
      },
    } as unknown as SessionStore;
    const orchestrator = {
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield text('working');
        await gate.until;
        yield STOP;
      },
    } as unknown as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler(orchestrator, sessionStore);

    const turn = handle(ws, session, {type: 'user_message', content: 'hello'});
    await afterPendingWork();
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    await handle(ws, session, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
    const framesWhileStreaming = [...sent];
    gate.release();
    await turn;

    expect({calls, framesWhileStreaming}).toEqual({
      calls: [{userId: 'u1', options: {limit: 10, before}}],
      framesWhileStreaming: [
        expect.objectContaining({type: 'entry_upsert'}),
        expect.objectContaining({type: 'entry_upsert'}),
        expect.objectContaining({type: 'entry_delta'}),
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when createMessageHandler is called without a sessionStore', async () => {
    const h = harness([]);

    await h.send({type: 'list_sessions'});

    expect(h.sent).toEqual([{type: 'session_list', sessions: []}]);
  });
});

